    function writeJsonStorage(key, value) {
      try {
        return writeStorage(key, JSON.stringify(value));
      } catch {
        return false;
      }
    }

    function draftKey(root, rel) {
      return `${DRAFT_PREFIX}${root}:${rel}`;
    }


