      macro: 'M',
      struct: 'T',
      class: 'T',
      union: 'T',
      enum: 'E',
      typedef: 'T',
      type: 'T',
      interface: 'T',
      variable: 'v',
      constant: 'C',
      member: '.',
      field: '.',
      parameter: 'p',
      namespace: 'N',
      label: 'L',
      include: '#',
