      method: 'func',
      call: 'func',
      macro: 'macro',
      define: 'macro',
      struct: 'type',
      class: 'type',
      union: 'type',
      enum: 'type',
      enum_member: 'type',
      typedef: 'type',
      type: 'type',
      interface: 'type',
      namespace: 'other',
      variable: 'var',
      constant: 'var',
      member: 'var',
      field: 'var',
      parameter: 'var',
      local: 'var',
      include: 'other',
      label: 'other',
