      preproc: [['path', { d: 'M2.9 2.4v7.2' }], ['path', { d: 'M2.9 3.1h6l-1.7 2.1 1.7 2.1h-6' }]],
      comment: [['path', { d: 'M2.6 3h6.8v4.2H5.9L3.5 9.3V7.2H2.6z' }]],
